function build(api) {
  api.name('Chibi Pokemon Trainer');
  const C_RED=0xcc2222, C_WHITE=0xf0f0f0, C_HAIR=0x8b4513, C_SKIN=0xffdab9, C_DGRAY=0x333333, C_BLACK=0x111111, C_DRED=0x991111;

  api.group('body','躯干');
    api.group('chest','胸');
      api.box({w:1.8,h:1.2,d:1.2,pos:[0,2.1,0],color:C_RED});
      api.box({w:1.6,h:0.3,d:0.1,pos:[0,2.55,0.65],color:C_WHITE});
    api.endGroup();
    api.group('abdomen','腹');
      api.box({w:1.6,h:0.6,d:1.1,pos:[0,1.2,0],color:C_DGRAY});
    api.endGroup();
    api.group('pelvis','胯');
      api.box({w:1.7,h:0.5,d:1.2,pos:[0,0.65,0],color:C_DGRAY});
    api.endGroup();
    api.group('backpack','背包');
      api.box({w:1.2,h:1.0,d:0.6,pos:[0,2.2,-0.9],color:C_DGRAY});
      api.box({w:0.8,h:0.15,d:0.15,pos:[0,2.7,-1.25],color:C_WHITE});
    api.endGroup();
  api.endGroup();

  api.group('head','头');
    api.sphere({r:1.5,pos:[0,4.5,0],color:C_SKIN});
    api.box({w:1.4,h:0.6,d:0.8,pos:[0,3.7,0.5],color:C_SKIN});
    api.group('cap','鸭舌帽');
      api.sphere({r:1.55,pos:[0,4.7,0],color:C_RED});
      api.box({w:3.2,h:0.12,d:1.0,pos:[0,4.15,0.8],color:C_RED});
      api.box({w:0.4,h:0.4,d:0.05,pos:[0,4.7,1.55],color:C_WHITE});
    api.endGroup();
    api.box({w:1.8,h:0.4,d:0.1,pos:[0,4.05,1.45],color:C_HAIR});
    api.box({w:0.5,h:0.5,d:0.1,pos:[-0.65,3.85,1.45],color:C_HAIR});
    api.box({w:0.5,h:0.5,d:0.1,pos:[0.65,3.85,1.45],color:C_HAIR});
    api.poly({r:0.25,pos:[-0.45,4.1,1.5],color:C_WHITE});
    api.poly({r:0.15,pos:[-0.45,4.1,1.55],color:C_BLACK});
    api.poly({r:0.25,pos:[0.45,4.1,1.5],color:C_WHITE});
    api.poly({r:0.15,pos:[0.45,4.1,1.55],color:C_BLACK});
    api.box({w:0.3,h:0.1,d:0.05,pos:[0,3.65,1.5],color:C_DRED});
  api.endGroup();

  api.mirror('x');
  api.group('leftArm','左臂');
    api.chain({waypoints:[[-1.2,2.4,0],[-1.5,1.5,0.2],[-1.3,0.8,0.3]],jointIds:['upperArm','forearm','hand'],r:0.3,color:C_RED});
    api.sphere({r:0.3,pos:[-1.3,0.8,0.3],color:C_SKIN});
  api.endGroup();
  api.group('leftLeg','左腿');
    api.chain({waypoints:[[-0.45,0.4,0],[-0.5,-0.8,0],[-0.5,-1.8,0.2]],jointIds:['thigh','shin','foot'],r:0.35,color:C_DGRAY});
    api.box({w:0.5,h:0.3,d:0.8,pos:[-0.5,-2.0,0.3],color:C_RED});
    api.box({w:0.5,h:0.1,d:0.85,pos:[-0.5,-2.2,0.3],color:C_WHITE});
  api.endGroup();
  api.endMirror();
}
